local RivetMaker = {}
local PRODUCTS = {
    iron_rivet = { name = "Železen zakovic", ironCost = 1, time = 1, cost = 2, shearStrength = 15, description = "Preprost železen zakovic za pločevino." },
    copper_rivet = { name = "Bakren zakovic", copperCost = 1, time = 1, cost = 6, shearStrength = 18, prestige = 1, description = "Bakren zakovic za dekorativne spoje." },
    steel_rivet = { name = "Jeklen zakovic", steelCost = 1, time = 2, cost = 12, shearStrength = 28, prestige = 1, description = "Jeklen zakovic za oklepe in ščite." },
    brass_rivet = { name = "Medeninast zakovic", brassCost = 1, time = 3, cost = 25, shearStrength = 22, prestige = 3, description = "Medeninast zakovic za usnjene oklepe." },
    silver_rivet = { name = "Srebrn zakovic", silverCost = 1, time = 4, cost = 60, shearStrength = 24, prestige = 6, happiness = 1, description = "Srebrn zakovic za ceremonialne oklepe." },
    royal_pure_gold_rivet = { name = "Kraljevski zlat zakovic", goldCost = 1, silverCost = 1, time = 6, cost = 250, shearStrength = 30, prestige = 18, happiness = 3, description = "Zlat zakovic za kraljevske insignije in okrasje." },
}
local BUILDINGS = {
    workshop = { name = "Zakovičarska delavnica", cost = { gold = 180, wood = 90 }, upkeep = 4, qualityBonus = 5 },
    forge = { name = "Zakovičarska kovačija", cost = { gold = 600, wood = 200, stone = 150 }, upkeep = 15, qualityBonus = 15 },
    heading_room = { name = "Glavčilnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 25, qualityBonus = 22 },
    royal_rivet_atelier = { name = "Kraljevski atelje zakovic", cost = { gold = 3000, wood = 400, stone = 500, gold = 30 }, upkeep = 60, qualityBonus = 36, prestigeBonus = 17 },
}
RivetMaker.ironStock = 20; RivetMaker.copperStock = 14; RivetMaker.steelStock = 12; RivetMaker.brassStock = 8; RivetMaker.silverStock = 5; RivetMaker.goldStock = 4
RivetMaker.productStock = {}; RivetMaker.buildings = {}; RivetMaker.maker = nil; RivetMaker.activeMaking = {}; RivetMaker.totalProducts = 0; RivetMaker.dayTimer = 0
function RivetMaker.init() RivetMaker.ironStock=20; RivetMaker.copperStock=14; RivetMaker.steelStock=12; RivetMaker.brassStock=8; RivetMaker.silverStock=5; RivetMaker.goldStock=4; RivetMaker.productStock={}; RivetMaker.buildings={}; RivetMaker.maker=nil; RivetMaker.activeMaking={}; RivetMaker.totalProducts=0; RivetMaker.dayTimer=0; print("[RivetMaker] Royal Rivet Maker System initialized (6 products, 4 buildings)") end
function RivetMaker.hireMaker(n,s) s=s or math.random(35,80); local c=230+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RivetMaker.maker={name=n or ("Zakovičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zakovičar najet: %s (spretnost: %d)",RivetMaker.maker.name,s),"success") end; return true end
function RivetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RivetMaker.build(id) local ok,e=RivetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RivetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RivetMaker.getQualityBonus() local b=0; for _,bd in ipairs(RivetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RivetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and RivetMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.copperCost and RivetMaker.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if d.steelCost and RivetMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.brassCost and RivetMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and RivetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RivetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #RivetMaker.buildings==0 then return false,"Potrebna delavnica" end; if not RivetMaker.maker then return false,"Potreben zakovičar" end; return true end
function RivetMaker.make(pt,qty) qty=qty or 20; local ok,e=RivetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then RivetMaker.ironStock=RivetMaker.ironStock-d.ironCost*qty end; if d.copperCost then RivetMaker.copperStock=RivetMaker.copperStock-d.copperCost*qty end; if d.steelCost then RivetMaker.steelStock=RivetMaker.steelStock-d.steelCost*qty end; if d.brassCost then RivetMaker.brassStock=RivetMaker.brassStock-d.brassCost*qty end; if d.silverCost then RivetMaker.silverStock=RivetMaker.silverStock-d.silverCost*qty end; if d.goldCost then RivetMaker.goldStock=RivetMaker.goldStock-d.goldCost*qty end; local t=d.time; if RivetMaker.maker then t=math.max(1,t-math.floor(RivetMaker.maker.skill/15)) end; table.insert(RivetMaker.activeMaking,{id="rivet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,shearStrength=d.shearStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RivetMaker.completeMaking(m) local q=1.0+(RivetMaker.getQualityBonus()/100); if RivetMaker.maker then q=q+(RivetMaker.maker.skill/200) end; q=math.min(2.0,q); RivetMaker.productStock[m.productType]=(RivetMaker.productStock[m.productType] or 0)+m.quantity; RivetMaker.totalProducts=RivetMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RivetMaker.maker then RivetMaker.maker.itemsMade=RivetMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then RivetMaker.maker.skill=math.min(100,RivetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zakovice izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function RivetMaker.update(dt) if not _G.state then return end; RivetMaker.dayTimer=RivetMaker.dayTimer+dt; if RivetMaker.dayTimer>=30 then RivetMaker.dayTimer=0; for i=#RivetMaker.activeMaking,1,-1 do local m=RivetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RivetMaker.completeMaking(m); table.remove(RivetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RivetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RivetMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RivetMaker.getStats() return {ironStock=RivetMaker.ironStock,copperStock=RivetMaker.copperStock,steelStock=RivetMaker.steelStock,brassStock=RivetMaker.brassStock,silverStock=RivetMaker.silverStock,goldStock=RivetMaker.goldStock,productStock=RivetMaker.productStock,numBuildings=#RivetMaker.buildings,hasMaker=RivetMaker.maker~=nil,makerName=RivetMaker.maker and RivetMaker.maker.name or "—",makerSkill=RivetMaker.maker and RivetMaker.maker.skill or 0,activeMaking=#RivetMaker.activeMaking,totalProducts=RivetMaker.totalProducts} end
return RivetMaker
